40	\begin{figure*}[t]
41	    \centering
42	    \begin{minipage}[t]{0.38\textwidth}
43	        \centering
44	        \includegraphics[width=\textwidth]{figures/paper/fig2_reward_trajectories.pdf}
45	        \centerline{\small (a) Reward trajectories}
46	    \end{minipage}
